from pathlib import Path
p = Path("shipping.py")
s = p.read_text()
old = s[s.index('if __name__'):]
new = '''def select_cheapest(parcel):
    """Pick the lowest-cost service; ties keep SERVICES order since no preference is set."""
    available = quotes(parcel)
    if not available:
        return {"id": parcel["id"], "status": "unavailable",
                "reason": f"no service covers zone '{parcel['zone']}'"}
    return {"id": parcel["id"], "status": "selected", **min(available, key=lambda q: q["cost"])}


def select_all(parcels):
    """One entry per parcel, in input order, so unavailable parcels are never dropped."""
    return {"parcels": [select_cheapest(p) for p in parcels]}


def write_selection(path):
    import json
    destination = Path(path)
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text(json.dumps(select_all(load()), indent=2) + "\\n")


if __name__ == "__main__":
    import json
    import sys
    if sys.argv[1:2] == ["select"]:
        write_selection(sys.argv[2] if len(sys.argv) > 2 else "build/quotes.json")
    else:
        print(json.dumps({p["id"]: quotes(p) for p in load()}, indent=2))
'''
p.write_text(s.replace(old, new))
EOF
cat >> tests/test_shipping.py <<'EOF'


def test_selects_cheapest_by_billable_weight():
    bulky = load()[0]
    assert select_cheapest(bulky) == {
        "id": "P1", "status": "selected", "service": "Express", "days": 2, "cost": 13.0}


def test_equal_price_keeps_service_table_order():
    compact = {"id": "X", "weight_kg": "2", "length_cm": "10", "width_cm": "10",
               "height_cm": "10", "zone": "urban"}
    assert select_cheapest(compact)["service"] == "Economy"
    assert [q["cost"] for q in quotes(bulky_with_equal_prices())] == [7.0, 6.0, 6.0]


def bulky_with_equal_prices():
    return {"id": "Y", "weight_kg": "2", "length_cm": "10", "width_cm": "10",
            "height_cm": "10", "zone": "urban"}


def test_unavailable_parcel_is_kept_in_input_order():
    entries = select_all(load())["parcels"]
    assert [e["id"] for e in entries] == ["P1", "P2", "P3"]
    assert entries[2]["status"] == "unavailable"
    assert "remote" in entries[2]["reason"]
